INSERT INTO `songs` (`id`, `title`, `slug`, `words`, `listen_link`, `download_link`, `album_id`, `singer_id`, `singer_duet_id`, `admin_id`, `category_id`, `year`, `time`, `kind`, `listen_count`, `status`, `deleted_at`, `created_at`, `updated_at`) VALUES
(128, 'مهرجان اعلنت الحرب على المجال  2024 غناء فيجو توزيع zuka', 'mhrgan-aaalnt-alhrb-aal-almgal-2024-ghnaaa-fygo-tozyaa-zuka', 'مش. عاوز بص \r\nجبتونا الارض                      \r\nف عنيكو القر \r\nالتزمو الصمت \r\n...                                                               Fifty Shopra   الحان انترو\r\nلابس مسك \r\nانا الاصل \r\nبتشيرتي الكت \r\nداخل ضغط \r\n....\r\nباشا طرابيش عاملنلي شنبه \r\nفي لساني ترابيس و دماغي مقفله                        zuka    الحان باقى الاغنيه\r\nانتو فانزات خدو صوره جنبنا          \r\nواخد اللقطه حضوري بيقتلك\r\n...                         \r\nماشي علي كيفي و بمزاجي \r\nدولا تلاميذ ووه في منهج ابتدائي \r\nلسه فبريكا ش تلاقو مني تاني \r\n\r\nالظاهر كده بتولع مني يسطا لما باجي \r\n....\r\nبقت ظيطه و زمبليطه \r\nاركنلي حبه جنب تيتا \r\nالكلام معانا زق في حيطه \r\nاه من خلفه العبيطه\r\n..\r\nمين ده اللي يرازينا \r\nاحنا نزرزر افندينا \r\nهنشربكو فخفخينا \r\nملينا ماكلام علينا \r\n.....\r\nلو لقينا الحب فيكو كنا نفضل نشتريكو \r\nاحنا ياما سلكنا ليكو و انتو مش سالكين \r\nلو هتيجو طب ما تيجو نفسي العب كوره بيكو \r\nللي اختار يلعب بالدح ميقولش اح بعدين \r\n....\r\nمنخافش م الاونطه نخافش م الخصوم يا \r\nتتعبو جوه شنطه او حتي في جيبي دميه \r\nطب ولا انا ولا انت و القفله ع العموم يا \r\nتتضمنش وجودي يسطا عشان انا مش بدوم يااااا\r\n...\r\nHey woo علي الله بطولي اسوقكو \r\nكاتم علي صوتكو \r\nعلينا الطلب انتو يسطا موتو \r\nبطل انا فيها طالع فوق فوق \r\n.....\r\nلما اشوطها بتيجي في الجون \r\nبالنسبه ليهم انا مارازون \r\nدايره سم ازميلي زي ال zone \r\nعليكم انا حاطط الله في اللعون \r\n....\r\nلما تحس اديني حس \r\nمش بجس مش بدس\r\nباجي اطس باجي اقص \r\nاحط كله في استربس \r\n...\r\nاوعي تنطق اي بم \r\nلو عويم تغرق في دم\r\nعايز تعيش دور المهم \r\nانا هعملك احلي فيلم يلا \r\n.....\r\nمش. عاوز بص \r\nجبتونا الارض \r\nف عنيكو القر \r\nالتزمو الصمت \r\n...\r\nلابس مسك \r\nانا الاصل \r\nبتشيرتي الكت \r\nداخل ضغط', 'https://archive.org/download/zuka_20240424/%D8%A7%D8%B9%D9%84%D9%86%D8%AA%20%D8%A7%D9%84%D8%AD%D8%B1%D8%A8%20%D8%B9%D9%84%D9%89%20%D8%A